<script setup lang="ts">
const api=useApi(),auth=useAuth()
type Workspace={id:string;name:string;role:string}
type Script={id:string;name:string;description:string;revision:number;etag?:string;archived_at:string|null}
type Version={id:string;version:number;state:string;source?:string;signing_bytes?:string;key_id?:string;key_revoked_at?:string|null}
type Key={id:string;name:string;public_key:string;revoked_at:string|null}
type Template={id:string;provider:string;language:string;source:string}
const spaces=ref<Workspace[]>([]),workspace=ref(''),scripts=ref<Script[]>([]),keys=ref<Key[]>([]),templates=ref<Template[]>([]),versions=ref<Version[]>([])
const scriptOffset=ref(0),keyOffset=ref(0),versionOffset=ref(0)
const selected=ref<Script|null>(null),version=ref<Version|null>(null),error=ref(''),busy=ref(false),notice=ref('')
const name=ref(''),description=ref(''),template=ref(''),language=ref('python'),provider=ref('local'),source=ref(''),targets=ref(''),schema=ref('[]'),timeout=ref(60),output=ref(262144)
const parser=ref('json'),outputSchema=ref('document'),sampleOutput=ref(''),parsedSample=ref<unknown>(null)
const keyName=ref(''),publicKey=ref(''),keyId=ref(''),signature=ref(''),password=ref(''),totp=ref(''),target=ref(''),params=ref('{}')
type Execution={id:string;state:string;mode:string;channel:string;created_at:string;error_code?:string|null;result?:unknown}
const executions=ref<Execution[]>([]),execution=ref<Execution|null>(null),executionOffset=ref(0),pendingExecution=ref<{fingerprint:string;key:string}|null>(null)
const base=computed(()=>`/workspaces/${workspace.value}/scripts`)
const role=computed(()=>spaces.value.find(s=>s.id===workspace.value)?.role)
const manage=computed(()=>auth.can('scripts.manage')&&['owner','manager'].includes(role.value||''))
const approve=computed(()=>auth.can('scripts.approve')&&role.value==='owner')
const execute=computed(()=>auth.can('scripts.execute')&&['owner','manager'].includes(role.value||''))
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=apiError(e).message}finally{busy.value=false;password.value='';totp.value=''}}
async function load(){sampleOutput.value='';parsedSample.value=null;scriptOffset.value=0;keyOffset.value=0;versionOffset.value=0;selected.value=null;version.value=null;executions.value=[];execution.value=null;executionOffset.value=0;pendingExecution.value=null;versions.value=[];signature.value='';keyId.value='';scripts.value=[];keys.value=[];templates.value=[];if(!workspace.value)return;const [a,b,c]=await Promise.all([api.get<{data:Script[]}>(base.value),api.get<{data:Key[]}>(base.value+'/keys'),api.get<{data:Template[]}>(base.value+'/templates')]);scripts.value=a.data;keys.value=b.data;templates.value=c.data}
async function open(id:string){sampleOutput.value='';parsedSample.value=null;versionOffset.value=0;version.value=null;executions.value=[];execution.value=null;executionOffset.value=0;pendingExecution.value=null;const a=await api.get<{data:Script}>(base.value+'/'+id);selected.value=a.data;name.value=a.data.name;description.value=a.data.description;versions.value=(await api.get<{data:Version[]}>(base.value+'/'+id+'/versions')).data}
async function page(kind:'scripts'|'keys'|'versions',delta:number){
  const pos=kind==='scripts'?scriptOffset:kind==='keys'?keyOffset:versionOffset
  const offset=Math.max(0,pos.value+delta)
  if(kind==='scripts')scripts.value=(await api.get<{data:Script[]}>(base.value+`?offset=${offset}`)).data
  else if(kind==='keys')keys.value=(await api.get<{data:Key[]}>(base.value+`/keys?offset=${offset}`)).data
  else if(selected.value)versions.value=(await api.get<{data:Version[]}>(base.value+`/${selected.value.id}/versions?offset=${offset}`)).data
  pos.value=offset
}
async function changeWorkspace(){sampleOutput.value='';parsedSample.value=null;parser.value='json';outputSchema.value='document';source.value='';schema.value='[]';targets.value='';target.value='';params.value='{}';name.value='';description.value='';signature.value='';password.value='';totp.value='';await load()}
async function openVersion(id:string){sampleOutput.value='';parsedSample.value=null;version.value=(await api.get<{data:Version}>(base.value+'/'+selected.value!.id+'/versions/'+id)).data;signature.value='';execution.value=null;executionOffset.value=0;pendingExecution.value=null;executions.value=[];if(execute.value)await loadExecutions()}
async function create(){const a=await api.write<{data:Script}>('POST',base.value,{name:name.value,description:description.value});await load();await open(a.data.id)}
async function metadata(archive=false){const s=selected.value!;await api.write(archive?'DELETE':'PATCH',base.value+'/'+s.id,archive?undefined:{name:name.value,description:description.value},true,{'If-Match':s.etag!});await load();await open(s.id)}
async function addVersion(){const id=selected.value!.id;const target_ids=targets.value.split(',').map(s=>s.trim()).filter(Boolean);const body=template.value?{template:template.value,target_ids}:{language:language.value,provider:provider.value,source:source.value,target_ids,parameters:JSON.parse(schema.value),timeout_seconds:timeout.value,output_limit_bytes:output.value,parser:provider.value==='local'?parser.value:'json',output_schema:provider.value==='local'?(parser.value==='prometheus'?'metrics':outputSchema.value):'document'};const a=await api.write<{data:Version}>('POST',base.value+'/'+id+'/versions',body);await open(id);await openVersion(a.data.id)}
async function changeKey(revoke?:string){await api.write('POST',base.value+'/keys'+(revoke?'/'+revoke+'/revoke':''),revoke?{password:password.value,totp:totp.value}:{name:keyName.value,public_key:publicKey.value,password:password.value,totp:totp.value});keyOffset.value=0;keys.value=(await api.get<{data:Key[]}>(base.value+'/keys')).data;if(selected.value)await open(selected.value.id)}
async function changeVersion(action:string){const id=selected.value!.id,v=version.value!.id;const body=action==='sign'?{key_id:keyId.value,signature:signature.value}:action==='validate'?{...(target.value?{target_id:target.value}:{}),parameters:JSON.parse(params.value)}:{password:password.value,totp:totp.value};const response=await api.write<{data:{execution_enabled?:boolean;channel?:string|null}}>('POST',base.value+'/'+id+'/versions/'+v+'/'+action,body);await open(id);await openVersion(v);notice.value=action==='validate'?`Подпись, состояние, target и параметры проверены. ${response.data.execution_enabled?'Канал разрешён: '+response.data.channel:'Исполнение не разрешено политикой или выключено.'}`:'Изменение сохранено.'}
async function parseSample(){
  parsedSample.value=null
  const body={...(target.value?{target_id:target.value}:{}),parameters:JSON.parse(params.value),sample_output:sampleOutput.value}
  const r=await api.write<{data:{sample:unknown}}>('POST',base.value+'/'+selected.value!.id+'/versions/'+version.value!.id+'/validate',body)
  parsedSample.value=r.data.sample
}
function downloadObservations(){
  const r=execution.value?.result as {normalized?:{schema?:string;observations?:Array<{external_id:string;type:string;fields:unknown}>};output?:{collector?:string}}|undefined
  if(execution.value?.channel!=='sandbox'||r?.normalized?.schema!=='observations'||!r.normalized.observations?.length||r.normalized.observations.length>200)return
  const payload=r.normalized.observations.map(({external_id,type,fields})=>({external_id,type,fields}))
  const blob=new Blob([JSON.stringify(payload)],{type:'application/json'});if(blob.size>524288){error.value='Превышен лимит Inventory Import (512 КиБ).';return}
  const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='inventory-observations.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)
}
const canExportObservations=computed(()=>{const r=execution.value?.result as {normalized?:{schema?:string;observations?:unknown[]};output?:{collector?:string}}|undefined;return execution.value?.channel==='sandbox'&&r?.normalized?.schema==='observations'&&!!r.normalized.observations?.length&&r.normalized.observations.length<=200})
const localVersion=computed(()=>{try{return JSON.parse(version.value?.signing_bytes||'{}').provider==='local'}catch{return false}})
function executionPath(){return base.value+'/'+selected.value!.id+'/versions/'+version.value!.id+'/executions'}
async function loadExecutions(delta=0){const offset=Math.max(0,executionOffset.value+delta);executions.value=(await api.get<{data:Execution[]}>(executionPath()+`?offset=${offset}`)).data;executionOffset.value=offset}
async function openExecution(id:string){execution.value=(await api.get<{data:Execution}>(executionPath()+'/'+id)).data}
async function enqueueExecution(mode:'execute'|'preview'){
  const body={mode,...(target.value?{target_id:target.value}:{}),parameters:JSON.parse(params.value)}
  const fingerprint=JSON.stringify([executionPath(),body]);if(pendingExecution.value?.fingerprint!==fingerprint)pendingExecution.value={fingerprint,key:crypto.randomUUID()}
  const a=await api.write<{data:Execution}>('POST',executionPath(),{...body,password:password.value,totp:totp.value},true,{'Idempotency-Key':pendingExecution.value.key});execution.value=a.data;pendingExecution.value=null;executionOffset.value=0;await loadExecutions();notice.value='Задание принято. Обработает отдельный script worker.'
}
async function cancelExecution(id:string){execution.value=(await api.write<{data:Execution}>('POST',executionPath()+'/'+id+'/cancel',{})).data;await loadExecutions()}
function downloadBytes(){if(!version.value?.signing_bytes)return;const url=URL.createObjectURL(new Blob([version.value.signing_bytes],{type:'application/octet-stream'}));const a=document.createElement('a');a.href=url;a.download='script-signing-bytes.json';a.click();URL.revokeObjectURL(url)}
onMounted(()=>run(async()=>{if(!auth.can('scripts.read'))return;spaces.value=(await api.get<{data:Workspace[]}>('/workspaces')).data;workspace.value=spaces.value[0]?.id||'';await load()}))
</script>
<template>
  <div><h1>Реестр скриптов</h1><p class="page-subtitle">Неизменяемые версии, подписи Ed25519 и утверждение. Изолированный локальный запуск и фиксированные удалённые коллекторы.</p>
    <UiAlert :message="error"/><p v-if="notice" role="status">{{notice}}</p>
    <section v-if="auth.can('scripts.read')"><label>Workspace <select v-model="workspace" :disabled="busy" @change="run(changeWorkspace)"><option v-for="w in spaces" :key="w.id" :value="w.id">{{w.name}}</option></select></label>
      <div v-if="workspace" class="card"><h2>Скрипты</h2><button v-for="s in scripts" :key="s.id" class="btn" :disabled="busy" @click="run(()=>open(s.id))">{{s.name}} {{s.archived_at?'(архив)':''}}</button>
      <div><button class="btn" :disabled="busy||scriptOffset===0" @click="run(()=>page('scripts',-50))">Назад</button><button class="btn" :disabled="busy||scripts.length!==50" @click="run(()=>page('scripts',50))">Далее</button></div>
      <div v-if="manage"><label>Название <input v-model="name" maxlength="255"/></label><label>Описание <input v-model="description" maxlength="1024"/></label><button class="btn" :disabled="busy||!name" @click="run(create)">Создать скрипт</button><button v-if="selected&&!selected.archived_at" class="btn" :disabled="busy" @click="run(()=>metadata())">Сохранить метаданные</button><button v-if="selected&&!selected.archived_at" class="btn" :disabled="busy" @click="run(()=>metadata(true))">Архивировать</button></div></div>
      <div v-if="selected" class="card"><h2>{{selected.name}} — версии</h2><button v-for="v in versions" :key="v.id" class="btn" :disabled="busy" @click="run(()=>openVersion(v.id))">v{{v.version}} · {{v.state}}</button>
      <div><button class="btn" :disabled="busy||versionOffset===0" @click="run(()=>page('versions',-50))">Назад</button><button class="btn" :disabled="busy||versions.length!==50" @click="run(()=>page('versions',50))">Далее</button></div>
      <div v-if="manage&&!selected.archived_at"><h3>Новая версия</h3><label>Шаблон <select v-model="template"><option value="">Свой код</option><option v-for="t in templates" :key="t.id" :value="t.id">{{t.id}}</option></select></label><label>UUID targets через запятую <input v-model="targets"/></label>
        <template v-if="!template"><label>Язык <select v-model="language"><option>python</option><option>bash</option><option>powershell</option><option>connector</option></select></label><label>Провайдер <select v-model="provider"><option v-for="p in ['local','ssh','winrm','snmp','proxmox','vmmanager']" :key="p">{{p}}</option></select></label><label>Исходный код (без секретов) <textarea v-model="source" rows="8" maxlength="65536"/></label><label>Схема параметров JSON <textarea v-model="schema" rows="3"/></label><template v-if="provider==='local'"><label>Формат вывода <select v-model="parser"><option value="json">JSON</option><option value="csv">CSV</option><option value="key_value">Key-value</option><option value="prometheus">Prometheus text</option></select></label><label v-if="parser!=='prometheus'">Схема результата <select v-model="outputSchema"><option value="document">Документ</option><option value="observations">Inventory observations</option><option value="metrics">Метрики</option><option value="events">События</option></select></label></template><label>Timeout (сек) <input v-model.number="timeout" type="number" min="1" max="90"/></label><label>Лимит вывода <input v-model.number="output" type="number" min="1024" max="262144"/></label></template><button class="btn" :disabled="busy" @click="run(addVersion)">Создать draft</button></div>
      <div v-if="version"><h3>Версия {{version.version}} — {{version.state}}</h3><pre style="white-space:pre-wrap;overflow-wrap:anywhere">{{version.source}}</pre><details><summary>Подписываемый manifest</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere">{{version.signing_bytes}}</pre></details><button class="btn" @click="downloadBytes">Скачать точные байты для подписи</button>
        <div v-if="manage&&version.state==='draft'&&!selected.archived_at"><label>Доверенный ключ <select v-model="keyId"><option v-for="k in keys.filter(k=>!k.revoked_at)" :key="k.id" :value="k.id">{{k.name}}</option></select></label><label>Подпись hex <input v-model="signature" maxlength="128"/></label><button class="btn" :disabled="busy||!keyId||signature.length!==128" @click="run(()=>changeVersion('sign'))">Передать на утверждение</button></div>
        <div v-if="approve&&version.state!=='revoked'"><button v-if="version.state==='pending_review'&&!selected.archived_at" class="btn" :disabled="busy||!password||totp.length!==6" @click="run(()=>changeVersion('approve'))">Утвердить (MFA ниже)</button><button class="btn" :disabled="busy||!password||totp.length!==6" @click="run(()=>changeVersion('revoke'))">Отозвать версию (MFA ниже)</button></div>
        <div v-if="execute&&version.state==='approved'&&!selected.archived_at"><label>Target UUID (пусто для local) <input v-model="target"/></label><label>Параметры JSON <textarea v-model="params"/></label><button class="btn" :disabled="busy" @click="run(()=>changeVersion('validate'))">Проверить без исполнения</button>
        <div v-if="localVersion"><label>Образец stdout (без секретов) <textarea v-model="sampleOutput" rows="5" maxlength="262144"/></label><button class="btn" :disabled="busy||!sampleOutput" @click="run(parseSample)">Проверить парсер без запуска</button><pre v-if="parsedSample" style="white-space:pre-wrap;overflow-wrap:anywhere">{{JSON.stringify(parsedSample,null,2)}}</pre></div>
        <p>Preview и запуск сохраняют результат без записи в Inventory. Для удалённого шаблона сначала разрешите использование credential в разделе коннекторов. Не вводите секреты в параметры.</p>
        <button class="btn" :disabled="busy||!password||totp.length!==6" @click="run(()=>enqueueExecution('preview'))">Preview (MFA)</button><button class="btn" :disabled="busy||!password||totp.length!==6" @click="run(()=>enqueueExecution('execute'))">Запустить (MFA)</button></div>
        <div v-if="execute"><h3>История моих запусков</h3><button class="btn" :disabled="busy" @click="run(()=>loadExecutions())">Обновить</button><p v-for="e in executions" :key="e.id"><button class="btn" :disabled="busy" @click="run(()=>openExecution(e.id))">{{e.created_at}} · {{e.mode}} · {{e.state}}</button> {{e.error_code||''}}</p><button class="btn" :disabled="busy||executionOffset===0" @click="run(()=>loadExecutions(-50))">Назад</button><button class="btn" :disabled="busy||executions.length!==50" @click="run(()=>loadExecutions(50))">Далее</button>
        <div v-if="execution"><p>{{execution.id}} · {{execution.state}} · {{execution.error_code||''}}</p><button class="btn" :disabled="busy" @click="run(()=>openExecution(execution!.id))">Обновить результат</button><button v-if="['queued','running'].includes(execution.state)" class="btn" :disabled="busy" @click="run(()=>cancelExecution(execution!.id))">Отменить</button><button v-if="canExportObservations" class="btn" @click="downloadObservations">Скачать JSON для Inventory Import</button><pre v-if="execution.result" style="white-space:pre-wrap;overflow-wrap:anywhere">{{JSON.stringify(execution.result,null,2)}}</pre></div></div></div></div>
      <div class="card"><h2>Доверенные ключи</h2><p v-for="k in keys" :key="k.id">{{k.name}} · {{k.revoked_at?'отозван':'действует'}} <code>{{k.public_key}}</code><button v-if="approve&&!k.revoked_at" class="btn" :disabled="busy||!password||totp.length!==6" @click="run(()=>changeKey(k.id))">Отозвать</button></p>
        <div><button class="btn" :disabled="busy||keyOffset===0" @click="run(()=>page('keys',-50))">Назад</button><button class="btn" :disabled="busy||keys.length!==50" @click="run(()=>page('keys',50))">Далее</button></div>
        <div v-if="approve||execute"><h3>Свежая MFA-проверка</h3><label>Пароль <input v-model="password" type="password" autocomplete="current-password"/></label><label>TOTP <input v-model="totp" inputmode="numeric" maxlength="6" autocomplete="one-time-code"/></label><template v-if="approve"><label>Имя ключа <input v-model="keyName"/></label><label>Публичный ключ Ed25519 hex <input v-model="publicKey" maxlength="64"/></label><button class="btn" :disabled="busy||!password||totp.length!==6||publicKey.length!==64" @click="run(()=>changeKey())">Добавить доверенный ключ</button></template></div></div>
    </section><p v-else>Недостаточно прав.</p>
  </div>
</template>
